script.setup:
// hilbertcurve computed Hilbert curves of orders 1-7 and a 3D one (recipe hilbertcurve.orders
// → hilbert.json). Each segment is a screen-space quad; between orders every point slides
// out of its parent cell (index / 4) so one curve grows into the next.
const data = await (await fetch(ctx.assets["hilbert.json"])).json();
const gl = ctx.gl;
const corner = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, corner);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, -1, 1, -1, 0, 1, 1, 1]), gl.STATIC_DRAW);
// Instance layout: a(3) b(3) parentA(3) parentB(3) t(1).
const build = (pts, dim, parent) => {
  const n = pts.length / dim, inst = new Float32Array((n - 1) * 13);
  const P = (i) => [pts[i * dim], pts[i * dim + 1], dim === 3 ? pts[i * dim + 2] : 0.5];
  for (let i = 0; i < n - 1; i++) inst.set([...P(i), ...P(i + 1), ...parent(i), ...parent(i + 1), i / (n - 1)], i * 13);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, corner);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, inst, gl.STATIC_DRAW);
  [[1, 3, 0], [2, 3, 3], [3, 3, 6], [4, 3, 9], [5, 1, 12]].forEach(([loc, size, off]) => {
    gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 52, off * 4); gl.vertexAttribDivisor(loc, 1);
  });
  gl.bindVertexArray(null);
  return { vao, count: n - 1 };
};
const orders = data.orders.map((o, k) => {
  const prev = k > 0 ? data.orders[k - 1].points : null;
  return build(o.points, 2, (i) => (prev ? [prev[(i >> 2) * 2], prev[(i >> 2) * 2 + 1], 0.5] : [0.5, 0.5, 0.5]));
});
const curve3d = data.curve3d ? build(data.curve3d.points, 3, () => [0.5, 0.5, 0.5]) : null;
const vs = `#version 300 es
layout(location=0) in vec2 a_corner; layout(location=1) in vec3 a_a; layout(location=2) in vec3 a_b;
layout(location=3) in vec3 a_pa; layout(location=4) in vec3 a_pb; layout(location=5) in float a_t;
uniform mat4 u_mvp; uniform float u_morph; uniform float u_width; uniform vec2 u_resolution;
out float v_t; out vec2 v_side; out float v_depth;
void main(){
  vec4 A = u_mvp * vec4(mix(a_pa, a_a, u_morph) - 0.5, 1.0), B = u_mvp * vec4(mix(a_pb, a_b, u_morph) - 0.5, 1.0);
  vec2 sa = A.xy / A.w * u_resolution * 0.5, sb = B.xy / B.w * u_resolution * 0.5;
  vec2 d = sb - sa; float len = length(d); vec2 dir = len > 1e-4 ? d / len : vec2(1.0, 0.0), nrm = vec2(-dir.y, dir.x);
  vec4 P = mix(A, B, a_corner.x);
  vec2 s = mix(sa, sb, a_corner.x) + dir * (a_corner.x * 2.0 - 1.0) * u_width * 0.5 + nrm * a_corner.y * u_width * 0.5;
  v_t = a_t; v_side = vec2(a_corner.y, 0.0); v_depth = P.w;
  gl_Position = vec4(s / (u_resolution * 0.5) * P.w, P.z, P.w);
}`;
const fs = `#version 300 es
precision highp float; in float v_t; in vec2 v_side; in float v_depth; out vec4 outColor;
uniform float u_time; uniform float u_flow; uniform float u_fog;
vec3 hue(float h){ return clamp(abs(fract(h + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0); }
void main(){
  vec3 c = mix(vec3(0.95), hue(0.58 + v_t * 0.75), 0.75);
  float pulse = pow(0.5 + 0.5 * sin((v_t * 6.0 - u_time * u_flow) * 6.2831), 10.0);
  float edge = 1.0 - abs(v_side.x) * 0.45;
  c = c * (0.55 + 0.45 * edge) + pulse * 0.6;
  c *= mix(1.0, clamp(2.4 - v_depth * 0.55, 0.25, 1.0), u_fog);
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, {
  orders, curve3d, maxOrder: orders.length,
  p: ctx.utils.createProgram(vs, fs),
  camera: ctx.utils.createOrbitCamera({ distance: 2.6, theta: 0.6, phi: 1.1 }),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
void main(){ vec2 q = v_uv - 0.5; outColor = vec4(mix(vec3(0.07, 0.07, 0.09), vec3(0.02, 0.02, 0.03), length(q) * 1.5), 1.0); }`),
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
ctx.utils.drawFullscreen(s.bg);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
const scale = h / 720;
if (u.u_mode === 1 && s.curve3d) {
  s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
  const model = mat4.multiply(mat4.fromYRotation(ctx.time * 0.25), mat4.fromXRotation(0.3));
  const mvp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 40, 0.05, 20), mat4.multiply(s.camera.getViewMatrix(), model));
  gl.enable(gl.DEPTH_TEST); gl.clear(gl.DEPTH_BUFFER_BIT);
  ctx.utils.setUniforms(s.p, { u_mvp: mvp, u_morph: 1, u_width: 5 * scale, u_fog: 1 });
  gl.bindVertexArray(s.curve3d.vao);
  gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, s.curve3d.count);
  gl.disable(gl.DEPTH_TEST);
  ctx.publish("order", "3D");
} else {
  // Order: either the slider, or a slow sweep 1 → max → 1 that rests on each whole order.
  let o = u.u_order;
  if (u.u_auto) {
    const span = s.maxOrder - 1, x = (ctx.time * u.u_speed + 2) % (span * 2), tri = x < span ? x : span * 2 - x;
    const f = Math.min(Math.max((tri - Math.floor(tri) - 0.4) / 0.6, 0), 1);
    o = 1 + Math.floor(tri) + f * f * (3 - 2 * f);
  }
  o = Math.min(Math.max(o, 1), s.maxOrder);
  const k = Math.min(Math.ceil(o - 1e-6), s.maxOrder), morph = k === 1 ? 1 : 1 - (k - o);
  const size = Math.min(w, h) * 0.9;
  const mvp = mat4.fromScaling(size / w * 2, size / h * 2, 1);
  const cell = size / 2 ** (k - 1 + morph);
  ctx.utils.setUniforms(s.p, { u_mvp: mvp, u_morph: k === 1 ? 1 : morph, u_width: Math.max(1.6 * scale, cell * 0.32), u_fog: 0 });
  gl.bindVertexArray(s.orders[k - 1].vao);
  gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, s.orders[k - 1].count);
  ctx.publish("order", Number(o.toFixed(2)));
}
gl.bindVertexArray(null);
